 check(argc==4,"usage: player-update-model-tests fixture sha root");const std::filesystem::path root=argv[3];const auto bytes=load(argv[1],argv[2],48U*1024*1024);const auto nb=load(root/prior_path,prior_hash,512U*1024*1024);Reader nr{nb};const auto fixture=read_notification_header(nr,root);const auto sources=frame_sources(fixture);Reader r{bytes};check(r.bytes(8)==Bytes({'M','H','4','U','U','M','O','1'})&&r.u()==9,"model fixture schema");check(digest(r)=="d4191ea404df1e9ade8fb401983e3497699dae5aa994937f7859c43f84403435","original ELF identity");const auto original=digest(r);check(original=="840ff88e66d8b1caadd4a301e402e58260df8bf2c08503360727c9f9ccabe1cb","original execution identity");const auto scene_count=r.u();check(scene_count==1,"model source scene count");std::vector<SceneInput>scenes;for(U i=0;i<scene_count;++i)scenes.push_back(read_scene(r,root));const auto identity=r.bytes(16),basis=r.bytes(64);
